text:
:root{--bg:#10141b;--card:#10141b;--row:#1a212c;--text:#fff;--muted:#9aa3b2;--blue:#6cb0ff;--purple:#8b8cf5;--green:#7fe0a0;--btn:#263a63;--track:#363c4a;--chip:#252a33;color-scheme:dark}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#000;--card:#10141b}}
:root[data-theme="dark"]{--bg:#000}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;height:100%;background:var(--bg);color:var(--text);font-family:Roboto,"Segoe UI",system-ui,-apple-system,Arial,sans-serif}
html,body{width:100%;height:100%;overflow:hidden;background:var(--card)}
body{display:block;padding:0}
.app{width:100%;max-width:none;height:100%;max-height:none;background:var(--card);border-radius:0;padding:20px max(20px,env(safe-area-inset-left,0px)) 14px max(20px,env(safe-area-inset-left,0px));display:flex;flex-direction:column;position:relative;overflow:hidden}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer;padding:0}
svg{fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.top{display:flex;justify-content:space-between;align-items:flex-start}
.eyebrow{font-size:14px;letter-spacing:.2px;color:#c3c9d4;text-transform:uppercase}
h1{margin:2px 0 0;font-size:29px;font-weight:700;line-height:1.2}
.round{width:40px;height:40px;border-radius:50%;background:#1d2430;display:grid;place-items:center;color:var(--blue);transition:.15s}
.round:active,.row-btn:active,.dl:active,.add:active{transform:scale(.97)}
.round svg{width:22px;height:22px}
.view{flex:1;min-height:0;display:none;flex-direction:column;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-width:none}
.view::-webkit-scrollbar{display:none}
.view>*{flex-shrink:0}
.view.on{display:flex}
.cloud-row{margin-top:22px;background:var(--row);border-radius:20px;height:51px;padding:0 17px 0 15px;display:flex;align-items:center;justify-content:space-between;width:100%}
.cloud-row .l{display:flex;align-items:center;gap:12px;font-size:19px}
.cloud-row .l svg{width:24px;height:24px;color:var(--blue)}
.status{display:flex;align-items:center;gap:8px;font-size:16px;color:var(--green)}
.status svg{width:21px;height:21px}
.status.off{color:var(--muted)}
.sec{display:flex;justify-content:space-between;align-items:center;margin:26px 0 12px}
.sec h2{margin:0;font-size:21px;font-weight:700}
.badge{min-width:26px;height:26px;border-radius:13px;background:var(--chip);display:grid;place-items:center;font-size:15px;color:#e5e7ec}
.dl{display:block;width:100%;text-align:left;background:var(--row);border-radius:22px;padding:16px 16px 14px;margin-bottom:11px;transition:.15s}
.dl .h{display:flex;justify-content:space-between;align-items:center;gap:14px;font-size:19px;font-weight:600}
.dl .h>span{flex:none;min-width:48px;text-align:right}
.dl .n{display:flex;align-items:center;gap:10px;min-width:0;flex:1}
.dl .n svg{width:22px;height:22px;color:#c9ced8;flex:none}
.dl .n span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.bar{height:7px;border-radius:4px;background:var(--track);margin:14px 0 11px;overflow:hidden}
.bar i{display:block;height:100%;border-radius:4px;transition:width .4s}
.dl .f{display:flex;justify-content:space-between;color:var(--muted);font-size:16px}
.dl.paused{opacity:.65}
.note{color:#8e97a6;font-size:17px;line-height:1.4;margin:14px 0 18px}
.add{margin-top:auto;width:100%;display:flex;align-items:center;gap:14px;text-align:left;background:var(--row);border-radius:22px;padding:14px 16px;transition:.15s}
.add .ic{flex:none;width:auto;height:auto;background:none;color:var(--blue);display:grid;place-items:center}
.add .ic svg{width:22px;height:22px;color:#c9ced8}
.add .tx{flex:1;min-width:0}
.add b{display:block;font-size:19px;font-weight:600}
.add small{display:block;margin-top:6px;font-size:16px;color:var(--muted)}
.add .chev{flex:none;width:20px;height:20px;color:var(--muted)}
nav{flex:none;display:flex;justify-content:space-between;padding:12px 4px 2px;margin-top:6px;background:var(--card);position:relative;z-index:2}
nav button{flex:1;display:flex;flex-direction:column;align-items:center;gap:5px;font-size:14px;color:#8c93a1;transition:.15s}
nav button svg{width:25px;height:25px}
nav button.on{color:#fff}
.list{display:flex;flex-direction:column;gap:10px;margin-top:22px}
.row-btn{display:flex;align-items:center;justify-content:space-between;background:var(--row);border-radius:18px;padding:15px 16px;font-size:17px;width:100%;text-align:left;transition:.15s}
.row-btn small{color:var(--muted);font-size:14px}
.sw{width:42px;height:24px;border-radius:12px;background:var(--track);position:relative;transition:.2s;flex:none}
.sw::after{content:"";position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:#fff;transition:.2s}
.sw.on{background:var(--blue)}.sw.on::after{left:21px}
.back{display:flex;align-items:center;gap:6px;margin-top:18px;color:var(--blue);font-size:16px}.back svg{width:20px;height:20px}.sh{font-size:21px;font-weight:700;margin:20px 0 10px}.st{background:var(--row);border-radius:22px;padding:16px}.st .h{display:flex;justify-content:space-between;align-items:center}.st .t{display:flex;align-items:center;gap:10px;font-size:19px;font-weight:600}.st .t svg{width:22px;height:22px}.pill{font-size:14px;padding:5px 12px;border-radius:14px;background:#2a303a;color:#cfd4dd}.pill.b{background:#16304f;color:#4da3ff}.st .nm{display:flex;justify-content:space-between;align-items:center;margin-top:16px;font-size:18px}.st .nm b{font-size:21px}.st p{margin:10px 0 0;color:#8e97a6;font-size:14px;line-height:1.4}.act{margin-top:16px;width:100%;background:var(--btn);border-radius:18px;padding:13px;font-size:17px;font-weight:600}
.st .f{display:flex;justify-content:space-between;align-items:center;gap:12px;color:var(--muted);font-size:16px}.st .bar{margin:14px 0 12px}.st p{margin:14px 0 0}
.seg{display:flex;margin:16px 0 12px}.seg button{flex:1;padding:14px 0;border-radius:26px;font-size:18px;font-weight:600;color:#8c8f96;transition:.2s}.seg button.on{background:#2a2b2e;color:#fff}
.stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.stat{background:var(--row);border-radius:20px;padding:14px 16px 15px}.stat svg{width:22px;height:22px;color:#7db4ff;display:block}.stat b{display:block;font-size:28px;font-weight:700;margin:10px 0 8px;line-height:1}.stat span{color:var(--muted);font-size:15px}
.pill.p{background:#2a2a52;color:#a9a8ff}.pill.g{background:#173a2a;color:var(--green)}.dl .n .pill{flex:none;font-size:12px;padding:3px 9px;overflow:visible}.act2{margin-top:16px;width:100%;background:#3b3a7a;border-radius:18px;padding:13px;font-size:17px;font-weight:600}
.modal{position:absolute;inset:0;background:rgba(0,0,0,.6);display:none;align-items:flex-end;z-index:5}
.modal.on{display:flex}
.sheet{width:100%;background:#161c26;border-radius:26px 26px 0 0;padding:22px 20px calc(22px + env(safe-area-inset-bottom,0px))}
.sheet h3{margin:0 0 14px;font-size:20px}
.sheet input{width:100%;background:var(--row);border:1px solid #2b3342;border-radius:14px;padding:14px;color:#fff;font:inherit;font-size:16px;outline:0}
.sheet input:focus{border-color:var(--blue)}
.sheet .acts{display:flex;gap:10px;margin-top:14px}
.sheet .acts button{flex:1;padding:13px;border-radius:14px;font-size:16px;font-weight:600;background:var(--chip)}
.sheet .acts .ok{background:var(--btn)}
.sheet .step{display:none}.sheet .step.on{display:block}
.grp{margin:12px 4px 0;font-size:13px;letter-spacing:.3px;text-transform:uppercase;color:var(--muted)}
.row-btn .val{flex:none;font-size:16px;font-weight:600;color:var(--blue)}
.row-btn>svg{flex:none;color:var(--muted)}
.row-btn.act-row>svg{color:var(--blue)}
.choice{display:flex;align-items:center;gap:14px;width:100%;height:78px;text-align:left;background:var(--row);border-radius:22px;padding:14px 16px;margin-bottom:11px;transition:.15s}
.choice:active{transform:scale(.97)}
.choice svg{width:22px;height:22px;color:#c9ced8;flex:none}
.choice .tx{flex:1;min-width:0}
.choice b{display:block;font-size:19px;font-weight:600}
.choice small{display:block;margin-top:5px;font-size:16px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.choice .chev{width:20px;height:20px;color:var(--muted)}
.sheet .cancel-full{width:100%;padding:13px;border-radius:14px;font-size:16px;font-weight:600;background:var(--chip);margin-top:3px}
.toast{position:absolute;left:50%;bottom:92px;transform:translate(-50%,20px);background:#2b3342;padding:10px 16px;border-radius:14px;font-size:14px;opacity:0;pointer-events:none;transition:.25s;z-index:6;white-space:nowrap}
.toast.on{opacity:1;transform:translate(-50%,0)}
.sheet.tall{max-height:90%;overflow-y:auto;scrollbar-width:none}
.plan{background:var(--row);border-radius:22px;padding:16px;margin-bottom:11px;border:1px solid transparent}
.plan.cur{border-color:#3b5f99}
.plan .pr{font-size:26px;font-weight:700;margin:10px 0 0}.plan .pr small{font-size:14px;color:var(--muted);font-weight:500}
.plan ul{list-style:none;margin:12px 0 0;padding:0;display:flex;flex-direction:column;gap:8px;font-size:16px}
.plan li::before{content:"\2713";color:var(--green);margin-right:10px}
.ad{display:block;width:100%;text-align:left;background:#1a1d24;border:1px dashed #3a4150;border-radius:18px;padding:12px 14px;margin-bottom:14px;color:var(--muted);font-size:13px}
.plans{display:grid;grid-template-columns:1fr 1fr;gap:10px}.plan{margin-bottom:0;padding:14px 12px;display:flex;flex-direction:column}.plan .pr{font-size:24px}.plan .d{color:var(--muted);font-size:14px;margin-top:6px;min-height:36px}.plan ul{font-size:14px;gap:10px;flex:1}.plan li::before{margin-right:8px}.pb{margin-top:16px;width:100%;padding:12px 4px;border-radius:14px;font-size:15px;font-weight:600;background:var(--chip)}.pb.ok{background:var(--btn)}.pb:disabled{opacity:.5}
.plans{gap:8px}
#planModal .plan{background:#000;border:1.5px solid #252a33;border-radius:20px;padding:16px 13px 14px}
#planModal #plPrem{background:#172338;border-color:#42689f}
#planModal .plan .pill{display:inline-block;font-size:13px;font-weight:600;padding:7px 13px;border-radius:15px;background:#262626;color:#d4d4d4}
#planModal .plan .pill.b{background:#15355c;color:#3d9bff}
#planModal .plan .pr{font-size:30px;font-weight:700;line-height:1;margin:18px 0 0}
#planModal .plan .pr small{font-size:13px;font-weight:600;color:#9a9ea6}
#planModal .plan .d{font-size:14px;line-height:1.35;color:#8d9097;margin-top:16px;min-height:0}
.dv{height:1px;background:rgba(255,255,255,.09);margin:16px 0 18px}
#planModal .plan ul{font-size:15px;line-height:1.3;gap:14px;margin:0}
#planModal .plan li::before{color:#2fc15f;margin-right:8px}
#planModal .sheet{padding-left:8px;padding-right:8px}
#planModal .plan{padding:14px 11px 12px;border-radius:18px}
#planModal .plan .pill{align-self:flex-start;font-size:12px;padding:6px 12px}
#planModal .plan .pr{font-size:26px;margin-top:16px}
#planModal .plan .pr small{font-size:12px}
#planModal .plan .d{font-size:13px;margin-top:14px}
.dv{margin:14px 0 16px}
#planModal .plan ul{font-size:13px;gap:12px}
#planModal .plan li::before{margin-right:6px}
.pb{font-size:14px;padding:11px 4px}

/* ===== Файлы ===== */
.fsum{margin-top:20px;background:var(--row);border-radius:24px;padding:18px 18px 16px}
.fsum .big{font-size:34px;font-weight:700;line-height:1;letter-spacing:-.5px}
.fsum .sub{margin-top:8px;font-size:15px;color:var(--muted)}
.fs-bar{display:flex;gap:3px;height:10px;margin:18px 0 16px}
.fs-bar i{display:block;min-width:6px;border-radius:5px;background:var(--c);transform-origin:left center;animation:fsgrow .8s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--k)*80ms)}
@keyframes fsgrow{from{transform:scaleX(0)}}
.fs-leg{display:grid;grid-template-columns:1fr 1fr;gap:10px 16px}
@media (max-width:380px){.fsum{padding:16px 14px 14px}.fs-leg div,.fs-leg b{font-size:13px}.fs-leg div{gap:6px}}
.fs-leg div{white-space:nowrap;display:flex;align-items:center;gap:8px;font-size:14px;color:var(--muted);min-width:0}
.fs-leg i{width:8px;height:8px;border-radius:50%;background:var(--c);flex:none}
.fs-leg b{margin-left:auto;font-weight:600;color:var(--text);font-size:14px}
.fsearch{position:relative;margin-top:14px}
.fsearch svg{position:absolute;left:15px;top:50%;width:20px;height:20px;margin-top:-10px;color:var(--muted);pointer-events:none}
.fsearch input{width:100%;height:46px;border:1px solid transparent;border-radius:16px;background:var(--row);color:#fff;font:inherit;font-size:16px;padding:0 14px 0 44px;outline:0;transition:.15s}
.fsearch input::placeholder{color:#7d8696}
.fsearch input:focus{border-color:#3b5f99}
.chips{display:flex;gap:8px;margin:12px 0 4px;padding:0 24px 0 0;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent)}
.chips::-webkit-scrollbar{display:none}
.chips button{flex:none;height:36px;padding:0 15px;border-radius:18px;background:var(--row);color:#b5bcc9;font-size:15px;font-weight:600;transition:.15s}
.chips button.on{background:#fff;color:#0b0e13}
.fgh{margin:22px 4px 9px;font-size:15px;font-weight:600;color:var(--muted)}
.fgrp{background:var(--row);border-radius:22px;overflow:hidden}
.fr{display:flex;align-items:center;gap:13px;width:100%;text-align:left;padding:12px 14px 12px 12px;transition:background .15s}
.fr+.fr{border-top:1px solid rgba(255,255,255,.06)}
.fr:active{background:#222b39}
.ft{width:46px;height:46px;border-radius:15px;background:var(--cb);color:var(--c);display:grid;place-items:center;flex:none}
.ft svg{width:23px;height:23px}
.fr .tx{flex:1;min-width:0}
.fr .nm2{font-size:17px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fr .lc{display:flex;align-items:center;gap:7px;margin-top:5px;font-size:14px;color:var(--muted)}
.fr .lc{white-space:nowrap}.fr .lc .pi{width:15px;height:15px;color:var(--purple);flex:none;margin-left:1px}
.fr .lc b{color:#c9ced8;font-weight:600;margin-right:3px}
.fr .lc i{width:6px;height:6px;border-radius:50%;background:var(--blue);flex:none}
.fr .lc i.ph{background:var(--purple)}
.fr .sz{flex:none;font-size:16px;font-weight:600;text-align:right}
.fr .chev{flex:none;width:18px;height:18px;color:#5d6676}
.fempty{text-align:center;padding:48px 24px 24px;color:var(--muted);line-height:1.45}
.fempty svg{width:34px;height:34px;color:#4a5363;margin-bottom:10px}
.fempty b{display:block;color:var(--text);font-size:18px;margin-bottom:6px}
.t-iso{--c:#6cb0ff;--cb:rgba(108,176,255,.14)}
.t-archive{--c:#9d9ef7;--cb:rgba(139,140,245,.16)}
.t-video{--c:#f0b86e;--cb:rgba(240,184,110,.14)}
.t-audio{--c:#7fe0a0;--cb:rgba(127,224,160,.13)}
.t-other{--c:#aab2c0;--cb:rgba(170,178,192,.13)}
.fhead{display:flex;align-items:center;gap:14px;margin-bottom:16px}
.fhead .tx{min-width:0;flex:1}
.fhead b{display:block;font-size:19px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fhead small{display:block;margin-top:4px;font-size:15px;color:var(--muted)}
.fa{display:flex;align-items:center;gap:14px;width:100%;text-align:left;background:var(--row);border-radius:18px;padding:15px 16px;margin-bottom:9px;font-size:17px;font-weight:600;transition:.15s}
.fa:active{transform:scale(.98)}
.fa svg{width:22px;height:22px;color:var(--blue);flex:none}
.fa small{display:block;margin-top:3px;font-size:14px;font-weight:400;color:var(--muted)}
.fa.ph svg{color:var(--purple)}
.fa.del{color:#ff8f8f}.fa.del svg{color:#ff8f8f}
.fa.dis{opacity:.6}.fa.dis svg{color:var(--green)}
@media (prefers-reduced-motion:reduce){.fs-bar i{animation:none}}

/* мягкое растворение контента под шапкой и над меню */
.view{-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 var(--ft,0px),#000 calc(100% - var(--fb,0px)),transparent 100%);mask-image:linear-gradient(to bottom,transparent 0,#000 var(--ft,0px),#000 calc(100% - var(--fb,0px)),transparent 100%)}

/* subscription only */
#planModal .sheet{background:var(--card);border:1px solid rgba(255,255,255,.06);border-bottom:0}
#planModal .plan{background:var(--row);border:1px solid rgba(255,255,255,.06)}
#planModal #plPrem{background:var(--row);border:1px solid rgba(255,255,255,.06);box-shadow:none}
#planModal .plan .pill{background:var(--chip);color:#cfd4dd}
#planModal .plan .pill.b{background:#16304f;color:#4da3ff}
#planModal .plan li::before{color:var(--green)}
#planModal .pb{background:var(--chip)}
#planModal .pb.ok{background:var(--chip);color:#fff}
#planModal .plan .d{min-height:calc(2*1.35em);line-height:1.35}

const ico='<svg viewBox="0 0 24 24"><path d="M14 3H7.5A2 2 0 0 0 5.5 5v14a2 2 0 0 0 2 2h9a2 2 0 0 0 2-2V7.5z"/><path d="M14 3v4.5h4.5"/><path d="M9.5 9.5h1.5M9.5 12h1.5"/><circle cx="10" cy="16.5" r="1.3"/></svg>';
const $=s=>document.querySelector(s);
const opt={auto:true,autoDel:false,limit:2,speedOn:false,speed:10,autoStart:true};
let plan='free';
const LIM={free:{n:1,gb:20,phone:false},prem:{n:5,gb:500,phone:true}};
const lim=()=>Math.min(opt.limit,LIM[plan].n);
const ev=v=>opt.speedOn?Math.min(v,opt.speed):v;
const names={downloads:'Загрузки',files:'Файлы',cloud:'Облако',settings:'Настройки'};
let dls=[
  {n:'Game_Archive.iso',p:68,ph:25,pv:12,phOn:true,s:'218 ГБ',v:85,c:'var(--blue)',on:true},
  {n:'Project_Assets.zip',p:34,ph:10,pv:8,phOn:true,s:'42 ГБ',v:21,c:'var(--purple)',on:true}
];
function render(){
  $('#dls').innerHTML=dls.map((d,i)=>`<button class="dl ${d.on?'':'paused'}" data-i="${i}">
    <div class="h"><div class="n">${ico}<span>${d.n}</span><span class="pill pl ${stat(d)[1]}">${stat(d)[0]}</span></div><span class="pc">${Math.floor(prog(d)[0])}%</span></div>
    <div class="bar"><i style="width:${prog(d)[0]}%;background:${prog(d)[1]}"></i></div>
    <div class="f"><span>${d.s} · <span class="eta">${etaT(d)}</span></span><span class="spd">${spdT(d)}</span></div></button>`).join('');
  renderCloud();renderPause();$('#count').textContent=dls.length;$('#stA').textContent=dls.length;$('#stS').textContent=Math.round(dls.reduce((a,d)=>a+parseFloat(d.s),0))+' ГБ';
  renderFiles();
}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('on'),1800)}
function tab(t){
  document.querySelectorAll('.view').forEach(v=>v.classList.toggle('on',v.id==='v-'+t));
  document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('on',b.dataset.tab===t));
  $('#title').textContent=names[t];
  if(t==='files')renderFiles();
}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
$('#cloudTop').onclick=()=>tab('cloud');
let cur=null,dtab='server';
function fmt(s){s=Math.ceil(s);if(s<60)return s+' с';const m=Math.ceil(s/60);if(m<60)return m+' мин';return Math.floor(m/60)+' ч '+(m%60)+' мин'}
const qList=()=>dls.filter(d=>d.on&&d.p<100);
const queued=d=>d.on&&d.p<100&&qList().indexOf(d)>=lim();
function stat(d){if(!d.on)return['Пауза',''];if(queued(d))return['Очередь',''];if(d.p<100)return['Cloud','b'];if(d.ph<100)return['Android','p'];return['Готово','g']}
function etaT(d){if(!d.on)return 'приостановлено';if(queued(d))return 'в очереди';if(d.p<100)return 'ещё ~'+fmt((100-d.p)/(ev(d.v)/200));if(d.ph<100)return d.phOn?'ещё ~'+fmt((100-d.ph)/(ev(d.pv)/200)):'ожидание';return 'готово'}
function spdT(d){if(!d.on)return 'Пауза';if(queued(d))return '—';if(d.p<100)return ev(d.v)+' МБ/с';if(d.ph<100&&d.phOn)return ev(d.pv)+' МБ/с';return d.ph>=100?'Готово':'—'}
