function allFiles(){
  const fromDl=dls.map((d,i)=>({d,i})).filter(x=>x.d.p>=100&&!x.d.cloudDel).map(x=>({id:'d'+x.i,n:x.d.n,gb:parseFloat(String(x.d.s).replace(',','.')),g:0,ph:x.d.ph>=100,d:x.d}));
  return fromDl.concat(fStatic).map(f=>({...f,t:ftype(f.n)}));
}
function renderFiles(){
  if(!$('#fSum'))return;
  const all=allFiles(),total=all.reduce((a,f)=>a+f.gb,0);
  const by={};all.forEach(f=>by[f.t]=(by[f.t]||0)+f.gb);
  const keys=Object.keys(FT).filter(k=>by[k]>0).sort((a,b)=>by[b]-by[a]);
