   <div class="fs-bar">${keys.map((k,j)=>`<i class="t-${k}" style="flex:${by[k]} 1 0;--k:${j}"></i>`).join('')}</div>
   <div class="fs-leg">${keys.map(k=>`<div class="t-${k}"><i></i>${FT[k].n}<b>${fg(by[k])}</b></div>`).join('')}</div>`;
  const q=fQuery.trim().toLowerCase();
