  if(!list.length){
    $('#fList').innerHTML=`<div class="fempty"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/></svg><b>Ничего не найдено</b>Измените запрос или выберите другой тип файлов.</div>`;return;
  }
  $('#fList').innerHTML=FG.map((g,gi)=>{
    const items=list.filter(f=>f.g===gi);if(!items.length)return'';
    return `<div class="fgh">${g}</div><div class="fgrp">`+items.map(f=>`<button class="fr t-${f.t}" data-id="${f.id}"><span class="ft">${fsvg(f.t)}</span><span class="tx"><div class="nm2">${esc(f.n)}</div><div class="lc"><b>${fg(f.gb)}</b><i></i>Cloud${f.ph?'<svg class="pi" viewBox="0 0 24 24" aria-label="Android"><rect x="6.5" y="2.5" width="11" height="19" rx="2.5"/><path d="M11 18.5h2"/></svg>':''}</div></span>${chevS}</button>`).join('')+'</div>';
  }).join('');
